import { AlchemystClient } from '@alchemystai/sdk';
import { parseArgs } from 'util';

async function main() {
    const { values } = parseArgs({
        args: process.argv.slice(2),
        options: {
            question: {
                type: 'string',
            },
        },
    });

    const question = values.question;
    if (!question) {
        console.error("Missing --question argument");
        process.exit(1);
    }

    const client = new AlchemystClient({
        apiKey: process.env.ALCHEMYST_AI_API_KEY,
    });

    const runId = process.env.ZEALT_RUN_ID || 'default-run-id';
    const fileName = `refunds-${runId}.md`;

    const content = `# Refund Policy
Our company offers a 30-day money-back refund policy for all purchases.
If you are not satisfied, you can request a full refund within 30 days of the original purchase date.
`;

    // 1. Ingest document
    await client.v1.context.add({
        content: content,
        context_type: 'resource',
        metadata: {
            file_name: fileName,
            source: 'documentation',
            group_name: 'policies'
        },
        scope: 'internal'
    });

    // 2. Search
    const searchRes = await client.v1.context.search({
        query: question,
        scope: 'internal',
        similarity_threshold: 0.7,
        limit: 5
    });

    // 3. Print
    if (searchRes.results && searchRes.results.length > 0) {
        for (const chunk of searchRes.results) {
            console.log(chunk.content);
        }
    } else {
        console.log("No results found.");
    }
}

main().catch(err => {
    console.error(err);
    process.exit(1);
});

